create table if not exists products(id bigint generated by default as identity primary key,name text not null,price integer not null check(price>0),category text not null,emoji text not null default '🛒',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists orders(id bigint generated by default as identity primary key,name text not null,phone text not null,address text not null,landmark text not null default '',total integer not null,status text not null default 'جديد',created_at timestamptz not null default now(),updated_at timestamptz);
create table if not exists order_items(id bigint generated by default as identity primary key,order_id bigint not null references orders(id) on delete cascade,product_id bigint not null,product_name text not null,qty integer not null check(qty>0),price integer not null check(price>=0));
insert into products(name,price,category,emoji) select v.name,v.price,v.category,v.emoji from (values ('لحم غنم',18000,'لحوم','🥩'),('لحم عجل',16000,'لحوم','🥩'),('حليب طازج',2500,'ألبان','🥛'),('لبن',2000,'ألبان','🥛'),('جبن أبيض',4500,'أجبان','🧀'),('جبن مثلثات',3500,'أجبان','🧀')) v(name,price,category,emoji) where not exists(select 1 from products);